drop table if exists camaras;
CREATE TABLE IF NOT EXISTS camaras(
  id int(11) NOT NULL AUTO_INCREMENT,
  local_id int(11) default 0,
  descripcion varchar(1024),
  directorio varchar(255),
  url_conexion varchar(255),
  sistema int(11) default 0, /*0 son las ip, 1 de grabador*/
  x int(11) default 0,
  y int(11) default 0,
  puerta int(11) default 0,
  salida int(11) default 0,
  encendida int(11) default 0,
  ipcamlive_alias varchar(255),
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);


drop table if exists nodos;
CREATE TABLE IF NOT EXISTS nodos(
  id int(11) NOT NULL AUTO_INCREMENT,
  camara_id1 int(11) default 0,
  camara_id2 int(11) default 0,
  x int(11) default 0,
  y int(11) default 0,
  orden int(11) default 0,
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

drop table if exists lineas;
CREATE TABLE IF NOT EXISTS lineas(
  id int(11) NOT NULL AUTO_INCREMENT,
  camara_id int(11) default 0,
  nombre varchar(255),
  x1 float default 0,
  y1 float default 0,
  x2 float default 0,
  y2 float default 0,
  eliminada int(11) default 0,
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

