drop table if exists personas;
CREATE TABLE IF NOT EXISTS personas(
  id int(11) NOT NULL AUTO_INCREMENT,
  local_id varchar(255),
  nombre varchar(1024) default '',
  cod_interno varchar(255),
  trabajador int(11) default 0,
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

drop table if exists estancias;
CREATE TABLE IF NOT EXISTS estancias(
  id int(11) NOT NULL AUTO_INCREMENT,
  persona_id int(11) default 0,
  camara_id int(11) default 0,
  fecha_ini timestamp default CURRENT_TIMESTAMP,
  fecha_fin timestamp default CURRENT_TIMESTAMP,
  notificacion_vista int(11) default 0,
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);


drop table if exists fotos;
CREATE TABLE IF NOT EXISTS fotos(
  id int(11) NOT NULL AUTO_INCREMENT,
  estancia_id int(11) default 0,
  nombre_real_antesconversion varchar(255),
  identificador_unico varchar(255),
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);



drop table if exists cruces_lineas;
CREATE TABLE IF NOT EXISTS cruces_lineas(
  id int(11) NOT NULL AUTO_INCREMENT,
  linea_id int(11) default 0,
  fecha timestamp default CURRENT_TIMESTAMP,
  direccion int(11) default 0, /*1: #de derexa de la panatalla hacia la izquierda;;;;2:#de izquierda de la panatalla hacia la derexa*/
  x_cruce int(11) default 0,
  y_cruce int(11) default 0,
  identificador varchar(255),
  created timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);



